// studio-tracker #172: the Orsay, Bilbao, Uffizi and Guggenheim NY galleries become part of the one-app /play shell.
// Once the one-app version is live and audited, their old pages.dev projects 301 every path (query kept) to the gallery's
// stable deep link on tjm.art. Those hosts are separate Cloudflare Pages projects, so they never reach this site's Worker:
// the redirects ship as a _redirects file per project (redirects/museum-pagesdev/<project>/_redirects, generated by
// scripts/write-museum-redirects.mjs from this map) that is copied into the project's public/ folder when TJ says go.
// museumRedirect() below is the reference behaviour the tests check; it is not wired into the Worker.
export const MUSEUM_ORIGIN = 'https://tjm.art';
export const MUSEUM_REDIRECTS = {
  'tjm-play-orsay': '/play/orsay/',
  'tjm-play-bilbao': '/play/bilbao/',
  'tjm-play-uffizi': '/play/uffizi/',
  'tjm-play-gugg-ny': '/play/gugg-ny/',
};
// Old to-cart.html links must keep working (the card): they land on the copy that lives on tjm.art.
export const TO_CART_PATH = '/play/to-cart.html';

export function museumRedirect(requestUrl) {
  const url = new URL(requestUrl);
  const project = url.hostname.replace(/\.pages\.dev$/, '');
  if (!url.hostname.endsWith('.pages.dev') || !Object.hasOwn(MUSEUM_REDIRECTS, project)) return null;
  const path = url.pathname === '/to-cart.html' ? TO_CART_PATH : MUSEUM_REDIRECTS[project];
  return { status: 301, location: `${MUSEUM_ORIGIN}${path}${url.search}` };
}

export function museumRedirectsFile(project) {
  const target = MUSEUM_REDIRECTS[project];
  // Cloudflare Pages keeps the query string on redirects; first matching rule wins.
  return [
    `# studio-tracker #172: generated by scripts/write-museum-redirects.mjs. Do not edit by hand.`,
    `/to-cart.html ${MUSEUM_ORIGIN}${TO_CART_PATH} 301`,
    `/* ${MUSEUM_ORIGIN}${target} 301`,
    '',
  ].join('\n');
}
